const tasks={
 tissue:{title:'Tissue extraction',category:'DELICATE FORCE REGULATION',description:'Regulate fingertip forces to extract a tissue without tearing it or disturbing the box.',shift:'Unseen tissue-package appearance in robot training, covered by human demonstrations.',rate:93},
 wiping:{title:'Board wiping',category:'SUSTAINED SURFACE CONTACT',description:'Maintain eraser–surface contact and regulate normal force for smooth, consistent wiping.',shift:'Transfer from a black square to a red triangle.',rate:83},
 egg:{title:'Egg placement',category:'GENTLE GRASPING & PLACEMENT',description:'Grasp stably and place gently, controlling contact to avoid slippage or damage.',shift:'Transfer from an orange egg to a cyan egg.',rate:73},
 block:{title:'Block stacking',category:'PRECISE GEOMETRIC ALIGNMENT',description:'Use visuo-tactile feedback for stable grasping, precise alignment, and controlled placement.',shift:'Transfer from rectangular to circular blocks.',rate:80}
};
let task='tissue',mode='id';
const data={id:[[60,53,47,47],[87,83,60,63],[93,83,73,80]],ood:[[27,13,0,0],[60,47,27,33],[73,60,40,53]]};
function renderTask(){const t=tasks[task];document.getElementById('task-category').textContent=t.category;document.getElementById('task-title').textContent=t.title;document.getElementById('task-description').textContent=t.description;document.getElementById('task-shift').textContent=t.shift;document.getElementById('task-rate').textContent=t.rate+'%';document.getElementById('task-panel').setAttribute('aria-labelledby','tab-'+task);document.getElementById('task-video').setAttribute('aria-label',t.title);}
function renderChart(){const labels=Object.values(tasks).map(t=>t.title),classes=['robot','aot','tacot'],methods=['Robot-only','Action-guided OT','TacOT'];document.getElementById('chart').innerHTML=labels.map((label,j)=>`<div class="chart-group"><h3>${label}</h3>${classes.map((c,k)=>`<div class="chart-row" aria-label="${label}, ${methods[k]}: ${data[mode][k][j]}%"><div class="track"><div class="bar ${c}" style="width:${data[mode][k][j]}%"></div></div><b>${data[mode][k][j]}%</b></div>`).join('')}</div>`).join('');document.getElementById('protocol').textContent=mode==='id'?'In-distribution evaluation · 30 closed-loop rollouts per method–task pair.':'Targeted out-of-distribution transfer · 15 rollouts per method–task pair. Test configurations are present in human demonstrations but absent from robot training.';}
document.querySelectorAll('[data-task]').forEach(button=>button.addEventListener('click',()=>{if(task===button.dataset.task)return;task=button.dataset.task;document.querySelectorAll('[data-task]').forEach(b=>{b.setAttribute('aria-selected',String(b===button));b.tabIndex=b===button?0:-1;});const video=document.getElementById('task-video');video.pause();video.poster=`assets/${task}.webp`;video.src=`assets/${task}.mp4`;video.load();renderTask();}));
document.querySelector('.task-tabs').addEventListener('keydown',event=>{const tabs=[...document.querySelectorAll('[data-task]')],n=tabs.indexOf(document.activeElement);if(n<0)return;let next;if(event.key==='ArrowRight')next=(n+1)%tabs.length;else if(event.key==='ArrowLeft')next=(n+tabs.length-1)%tabs.length;else if(event.key==='Home')next=0;else if(event.key==='End')next=tabs.length-1;else return;event.preventDefault();tabs[next].focus();tabs[next].click();});
['id','ood'].forEach(value=>document.getElementById(value+'-mode').addEventListener('click',()=>{mode=value;['id','ood'].forEach(v=>{const b=document.getElementById(v+'-mode');b.classList.toggle('active',v===mode);b.setAttribute('aria-pressed',String(v===mode));});renderChart();}));
document.querySelectorAll('[data-task]').forEach(b=>b.tabIndex=b.getAttribute('aria-selected')==='true'?0:-1);renderTask();renderChart();

